INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT127-S1-Q11$batch04$, 127, 1, 11, $batch04$Paradox$batch04$, $batch04$Studies have shown that the more high-stress points a bridge has, the more likely it is to fracture eventually. This might lead one to expect fractures to develop at high-stress points. Surprisingly, however, fractures develop not at high-stress points but elsewhere on the bridge.$batch04$, $batch04$Which one of the following, if true, contributes most to an explanation of why bridges fracture elsewhere than at high-stress points?$batch04$, $batch04$B$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=127 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q11$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$In many structures other than bridges, such as ship hulls and airplane bodies, fractures do not develop at high-stress points.$batch04$, $batch04$Irrelevant Comparison$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$Fractures do not develop at high-stress points, because bridges are reinforced at those points; however, stress is transferred to other points on the bridge where it causes fractures.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$In many structures, the process of fracturing often causes high-stress points to develop.$batch04$, $batch04$Deepens Paradox$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Structures with no high-stress points can nonetheless have a high probability of fracturing.$batch04$, $batch04$Half Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$Improper bridge construction, e.g., low-quality welding or the use of inferior steel, often leads both to the development of high-stress points and to an increased probability of fracturing.$batch04$, $batch04$Half Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$The more high-stress points a bridge has, the more likely it is to fracture.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$The fractures develop somewhere other than the high-stress points?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Both facts have to fit. High-stress points must raise the risk of fracture, yet the break happens elsewhere. So the stress has to cause trouble somewhere else on the bridge.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a way high-stress points lead to fractures at other points.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT127-S1-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Other structures having the same pattern does not explain why it happens in bridges.$batch04$), ($batch04$B$batch04$, $batch04$Builders reinforce the high-stress points, so those points hold. The stress moves to weaker parts of the bridge and causes the fracture there. More high-stress points means more stress moved around, and so a higher chance of fracture.$batch04$), ($batch04$C$batch04$, $batch04$If fracturing creates high-stress points, fractures and high-stress points should show up in the same place. That is the opposite of what we see.$batch04$), ($batch04$D$batch04$, $batch04$This explains how fractures can happen without high-stress points, but not why more high-stress points still make a fracture more likely.$batch04$), ($batch04$E$batch04$, $batch04$Bad construction explains why high-stress points and fractures go together. It does not explain why the fractures land somewhere else.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT127-S1-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
